let selected_command = dynamic(${command:json});
let selected_version = dynamic(${cliVersion:json});
let command_values = iff(gettype(selected_command) == "array", selected_command, pack_array(tostring(selected_command)));
let version_values = iff(gettype(selected_version) == "array", selected_version, pack_array(tostring(selected_version)));
LiftoffCommandEvents_CL
| where TimeGenerated >= ago(180d)
| where $__timeFilter(TimeGenerated)
| where (set_has_element(command_values, "All") or Command in (command_values))
| where (set_has_element(version_values, "All") or CliVersion in (version_values))
| summarize TotalEvents = count()
| extend Observation = case(TotalEvents > 0, "Matching recorded events", set_has_element(command_values, "All") and set_has_element(version_values, "All"), "No recorded events in selected time range", "No events matching selected filters")

